/**
 * Every string the mutation instrument shows, in the instrument register:
 * lowercase, middot-separated, mechanism facts only. Anything quoting a
 * real header or a real cookie keeps straight quotes and real casing.
 */

/** Chrome, top-right: the cause view — the one round trip, as it went. */
export const VIEW_LABEL = "request";

/** The form's one action, and its pending label. */
export const SUBMIT_LABEL = "Add one";
export const SUBMIT_PENDING_LABEL = "Adding one…";

/** Under the form: the no-JavaScript path, stated rather than promised. */
export const FORM_NOTE =
  "works with JavaScript off · then it is a plain form post to the same function";

/** Under the count: where the number was read, and who cannot read it. */
export const COUNT_NOTE =
  "read on the server from an httpOnly cookie · your JavaScript cannot see it";

/** The count's fallback while the cookie is read. */
export const COUNT_PENDING = "reading your cookie on the server…";

/** The request view before any press: nothing has gone out yet. */
export const REQUEST_EMPTY =
  "no request yet · add one and the round trip appears here";

/** The seam under the request view: the three facts the card proves. */
export const REQUEST_SEAM =
  "one POST to the page’s own URL · the function is named in a header · the re-render rides back in the same response";

/** The seam under the page view. */
export const PAGE_SEAM =
  "the form calls the function · the function writes the cookie · the page re-renders around it";

/** Labels for the two halves of the card. */
export const REQUEST_HEADING = "request";
export const RESPONSE_HEADING = "response";

/** The response line no client can verify — and the reason it cannot. */
export const RSC_LINE = "the re-rendered page, as an RSC payload";
export const COOKIE_HIDDEN_NOTE =
  "visible in the network tab · absent from document.cookie";

"use server";

import { cookies, headers } from "next/headers";
import { COUNT_COOKIE, MAX_COUNT, parseCount } from "./count-parser";

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

/**
 * What the action saw and did, read from the real request — the request
 * view draws this and nothing else. Every field is something the function
 * can only know because the round trip happened: the action id arrives as
 * a header, the body's content type arrives as a header, and the cookie
 * line is the exact one the response carries back.
 */
export interface PressReceipt {
  /** The `Next-Action` header: the function's id, which is the whole route. */
  actionId: string;
  /** The `Content-Type` the browser chose for the form body. */
  contentType: string;
  /** The count after this press. */
  count: number;
  /** The path the POST went to — the page's own. */
  path: string;
  /** The `Set-Cookie` line the response carries, as set. */
  setCookie: string;
}

/**
 * The entire backend of the mutation demo. No API route, no fetch, no JSON —
 * the form invokes this function on the server, the server rewrites the
 * cookie, and Next.js re-renders the page so every Server Component reading
 * that cookie shows the new value. The signature matches what
 * `useActionState` passes: (previousState, formData). It returns its
 * receipt so the request view can show the round trip that actually ran.
 */
export async function pressTheButton(
  _previous: PressReceipt | null,
  _formData: FormData
): Promise<PressReceipt> {
  const [jar, incoming] = await Promise.all([cookies(), headers()]);
  const count = Math.min(
    parseCount(jar.get(COUNT_COOKIE)?.value) + 1,
    MAX_COUNT
  );

  const options = {
    httpOnly: true,
    maxAge: ONE_YEAR_SECONDS,
    path: "/",
    sameSite: "lax",
  } as const;
  jar.set(COUNT_COOKIE, String(count), options);

  return {
    actionId: incoming.get("next-action") ?? "",
    contentType: (incoming.get("content-type") ?? "").split(";")[0],
    count,
    path: pathnameOf(incoming.get("referer")),
    setCookie: `${COUNT_COOKIE}=${count}; Path=${options.path}; Max-Age=${options.maxAge}; HttpOnly; SameSite=Lax`,
  };
}

/** The page's own path, from the referer the browser sends with the POST. */
function pathnameOf(referer: string | null): string {
  if (!referer) {
    return "";
  }
  try {
    return new URL(referer).pathname;
  } catch {
    return "";
  }
}

import type { PressReceipt } from "./actions";
import {
  COOKIE_HIDDEN_NOTE,
  REQUEST_EMPTY,
  REQUEST_HEADING,
  RESPONSE_HEADING,
  RSC_LINE,
} from "./copy";

interface RequestCardProps {
  receipt: PressReceipt | null;
}

/** One line of the exchange: a header name and its value, as sent. */
function Line({
  name,
  value,
  muted,
}: {
  muted?: boolean;
  name: string;
  value: string;
}) {
  return (
    <p className="flex flex-wrap gap-x-2 font-mono text-xs/5">
      <span className="text-muted-foreground">{name}</span>
      <span
        className={
          muted
            ? "text-muted-foreground/80"
            : "break-all text-ht-cyan-800 dark:text-ht-cyan-300"
        }
      >
        {value}
      </span>
    </p>
  );
}

function Half({
  children,
  heading,
}: {
  children: React.ReactNode;
  heading: string;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <p className="font-mono font-semibold text-[0.65rem] text-muted-foreground uppercase tracking-[0.2em]">
        {heading}
      </p>
      {children}
    </div>
  );
}

/**
 * The round trip, drawn from the action's own receipt: what the browser
 * sent, and what came back. Nothing here is a script of what a request
 * looks like — every value was read from the request that carried the
 * press, and the cookie line is the one the response set.
 */
export function RequestCard({ receipt }: RequestCardProps) {
  if (!receipt) {
    return (
      <p className="font-mono text-muted-foreground text-xs/5">
        {REQUEST_EMPTY}
      </p>
    );
  }

  return (
    <div className="grid gap-5 rounded-xl border border-ht-cyan-700/30 border-dashed bg-muted/20 px-4 py-4 sm:px-5 dark:border-ht-cyan-500/30">
      <Half heading={REQUEST_HEADING}>
        <Line name="POST" value={receipt.path || "this page"} />
        <Line name="Next-Action:" value={receipt.actionId} />
        <Line name="Content-Type:" value={receipt.contentType} />
      </Half>
      <Half heading={RESPONSE_HEADING}>
        <Line name="Set-Cookie:" value={receipt.setCookie} />
        <Line muted name="" value={COOKIE_HIDDEN_NOTE} />
        <Line name="body" value={RSC_LINE} />
      </Half>
    </div>
  );
}

"use client";

import { Switch } from "@repo/design-system/components/ui/switch";
import { cn } from "@repo/design-system/lib/utils";
import { useActionState, useCallback, useState } from "react";
import { MarketingButton } from "../../components/marketing-button";
import { LivePanel } from "../live-panel";
import { pressTheButton } from "./actions";
import {
  FORM_NOTE,
  PAGE_SEAM,
  REQUEST_SEAM,
  SUBMIT_LABEL,
  SUBMIT_PENDING_LABEL,
  VIEW_LABEL,
} from "./copy";
import { RequestCard } from "./request-card";

type View = "page" | "request";

interface MutationPanelProps {
  /**
   * The count, rendered on the server from the cookie and handed across
   * the boundary as a finished slot. The panel never reads the cookie —
   * it cannot, which is the chapter's point.
   */
  count: React.ReactNode;
  references: React.ReactNode;
}

/**
 * The client owner of the mutation instrument. It owns the form (a form
 * whose `action` is a server function — with JavaScript, `useActionState`
 * adds a pending flag and skips the full reload; without it, a plain form
 * post still runs the same function), the view switch, and the gauge.
 *
 * The request view draws the action's receipt: what the last press sent
 * and what came back, read from the real request. Before the first press
 * it says so rather than showing a sample.
 */
export function MutationPanel({ count, references }: MutationPanelProps) {
  const [receipt, formAction, pending] = useActionState(pressTheButton, null);
  const [view, setView] = useState<View>("page");

  const handleViewChange = useCallback((checked: boolean) => {
    setView(checked ? "request" : "page");
  }, []);

  const viewControls = (
    <div className="flex items-center gap-2.5">
      <label
        className="cursor-pointer select-none font-mono font-semibold text-[0.7rem] text-muted-foreground uppercase tracking-[0.2em]"
        htmlFor="mutation-request-view"
      >
        {VIEW_LABEL}
      </label>
      <Switch
        checked={view === "request"}
        id="mutation-request-view"
        onCheckedChange={handleViewChange}
      />
    </div>
  );

  // The form stays in the body: it is the specimen, not instrument chrome.
  // A form wired straight to a server function is the entire lesson, and
  // filing it under the deck would file the subject under controls.
  const form = (
    <form action={formAction} className="flex flex-col gap-3">
      <div>
        <MarketingButton disabled={pending} type="submit">
          {pending ? SUBMIT_PENDING_LABEL : SUBMIT_LABEL}
        </MarketingButton>
      </div>
      <p className="font-mono text-muted-foreground text-xs/5">{FORM_NOTE}</p>
    </form>
  );

  return (
    <LivePanel
      references={references}
      status={pending ? "working" : "live"}
      viewControls={viewControls}
    >
      <div className="flex flex-col gap-6">
        {/* Both views stacked in one grid cell, the inactive one invisible
            but holding its space, so flipping the switch never moves the
            form beneath it. */}
        <div className="grid">
          <div
            aria-hidden={view !== "page"}
            className={cn("[grid-area:1/1]", view !== "page" && "invisible")}
          >
            {count}
          </div>
          <div
            aria-hidden={view !== "request"}
            className={cn(
              "[grid-area:1/1]",
              view !== "request" && "invisible"
            )}
          >
            <RequestCard receipt={receipt} />
          </div>
        </div>
        {form}
        <p
          className="grid font-mono text-muted-foreground text-xs/5"
          role="status"
        >
          <span
            aria-hidden={view !== "page"}
            className={cn("[grid-area:1/1]", view !== "page" && "invisible")}
          >
            {PAGE_SEAM}
          </span>
          <span
            aria-hidden={view !== "request"}
            className={cn(
              "[grid-area:1/1]",
              view !== "request" && "invisible"
            )}
          >
            {REQUEST_SEAM}
          </span>
        </p>
      </div>
    </LivePanel>
  );
}

